import java.util.*;

public class GreedyExamples {

    /**
     * 活动选择：按结束时间排序，选最多不重叠活动
     * 时间 O(n log n)，空间 O(1)（排序用 O(log n) 栈空间）
     */
    public int activitySelection(int[] start, int[] end) {
        int n = start.length;
        int[][] acts = new int[n][2];
        for (int i = 0; i < n; i++) acts[i] = new int[]{start[i], end[i]};
        Arrays.sort(acts, Comparator.comparingInt(a -> a[1])); // 按结束时间升序

        int count = 1;
        int lastEnd = acts[0][1];
        for (int i = 1; i < n; i++) {
            if (acts[i][0] >= lastEnd) { // 不重叠则选中
                count++;
                lastEnd = acts[i][1];
            }
        }
        return count;
    }

    /**
     * 跳跃游戏：维护 maxReach，O(n)
     */
    public boolean canJump(int[] nums) {
        int maxReach = 0;
        for (int i = 0; i < nums.length; i++) {
            if (i > maxReach) return false; // 走不到 i
            maxReach = Math.max(maxReach, i + nums[i]);
        }
        return true;
    }

    /**
     * 发糖果：两次扫描，O(n)
     * 从左到右保证递增，从右到左保证递减
     */
    public int candy(int[] ratings) {
        int n = ratings.length;
        int[] candies = new int[n];
        Arrays.fill(candies, 1);
        for (int i = 1; i < n; i++) { // 左→右：比左边高则 +1
            if (ratings[i] > ratings[i - 1]) candies[i] = candies[i - 1] + 1;
        }
        for (int i = n - 2; i >= 0; i--) { // 右→左：比右边高则取 max
            if (ratings[i] > ratings[i + 1]) candies[i] = Math.max(candies[i], candies[i + 1] + 1);
        }
        int total = 0;
        for (int c : candies) total += c;
        return total;
    }

    /**
     * 零钱兑换贪心反例演示：coins=[1,3,4], amount=6
     * 贪心得 3 枚(4+1+1)，DP 得 2 枚(3+3)
     */
    public int coinChangeGreedy(int[] coins, int amount) {
        Arrays.sort(coins);
        int count = 0;
        for (int i = coins.length - 1; i >= 0; i--) {
            while (amount >= coins[i]) { amount -= coins[i]; count++; }
        }
        return amount == 0 ? count : -1;
    }

    public int coinChangeDP(int[] coins, int amount) {
        int[] dp = new int[amount + 1];
        Arrays.fill(dp, amount + 1);
        dp[0] = 0;
        for (int i = 1; i <= amount; i++) {
            for (int coin : coins) {
                if (coin <= i) dp[i] = Math.min(dp[i], dp[i - coin] + 1);
            }
        }
        return dp[amount] > amount ? -1 : dp[amount];
    }
}
